<div class="knowledge-page">
<header class="page-header"><div><p class="muted"><?= e(t('YOUR LOCAL KNOWLEDGE')) ?></p><h1><?= e(t('Keep ideas connected.')) ?></h1><p class="muted"><?= e(t('Notes live on this computer alongside your plans. Search, organize and link what matters.')) ?></p></div><a class="btn" href="/knowledge/new"><?= e(t('+ New note')) ?></a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<nav class="knowledge-actions" aria-label="Knowledge shortcuts"><a href="/knowledge/daily"><?= e(t('Open today\'s note')) ?></a><a href="/knowledge/new?template=meeting"><?= e(t('Meeting template')) ?></a><a href="/knowledge/new?template=project"><?= e(t('Project template')) ?></a><a href="/knowledge/new?template=learning"><?= e(t('Learning template')) ?></a></nav>
<form class="card knowledge-filters" method="get" action="/knowledge"><label><?= e(t('Search')) ?><input type="search" name="q" maxlength="200" value="<?= e($q) ?>" placeholder="Title or note text"></label><label><?= e(t('Notebook')) ?><select name="notebook"><option value=""><?= e(t('All notebooks')) ?></option><?php foreach ($notebooks as $name): ?><option value="<?= e($name) ?>" <?= $notebook===$name?'selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select></label><label><?= e(t('Tag')) ?><select name="tag"><option value=""><?= e(t('All tags')) ?></option><?php foreach ($allTags as $name): ?><option value="<?= e($name) ?>" <?= $tag===$name?'selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select></label><label><?= e(t('View')) ?><select name="state"><option value="active" <?= $state==='active'?'selected':'' ?>><?= e(t('Active')) ?></option><option value="archived" <?= $state==='archived'?'selected':'' ?>><?= e(t('Archived')) ?></option><option value="trash" <?= $state==='trash'?'selected':'' ?>><?= e(t('Trash')) ?></option></select></label><label><?= e(t('Sort')) ?><select name="sort"><option value="recent" <?= $sort==='recent'?'selected':'' ?>><?= e(t('Recently updated')) ?></option><option value="title" <?= $sort==='title'?'selected':'' ?>><?= e(t('Title')) ?></option></select></label><button class="secondary"><?= e(t('Apply')) ?></button></form>
<p class="muted"><?= e(count($rows)) ?> <?= e(t('of')) ?> <?= e($total) ?> <?= e(t('matching notes')) ?><?= $total>200?' · Showing first 200':'' ?>.</p>
<?php if (!$rows): ?><div class="card"><p class="muted"><?= e(t('No notes match this view.')) ?> <a href="/knowledge/new"><?= e(t('Capture your first idea.')) ?></a></p></div><?php endif; ?>
<div class="knowledge-grid"><?php foreach ($rows as $note): ?><article class="card knowledge-card"><div class="knowledge-meta"><span><?= e($note['notebook']) ?></span><?php if ($note['pinned']): ?><span><?= e(t('📌 Pinned')) ?></span><?php endif; ?><?php if ($note['archived']): ?><span><?= e(t('Archived')) ?></span><?php endif; ?></div><h2><a href="/knowledge/<?= e($note['id']) ?>"><?= e($note['title']) ?></a></h2><p><?= e(mb_substr(preg_replace('/\s+/u',' ',$note['body']) ?? '',0,170)) ?></p><div class="knowledge-tags"><?php foreach (array_filter(array_map('trim',explode(',',$note['tags']))) as $tagName): ?><a href="/knowledge?tag=<?= rawurlencode($tagName) ?>"><?= e($tagName) ?></a><?php endforeach; ?></div><small><?= e(t('Updated')) ?> <?= e($note['updated_at']) ?></small></article><?php endforeach; ?></div>
<details class="card knowledge-import"><summary><?= e(t('Import a Markdown note')) ?></summary><form action="/knowledge/import" method="post" enctype="multipart/form-data"><?= csrf_field() ?><label><?= e(t('UTF-8 .md file, up to 50 KB')) ?><input type="file" name="markdown" accept=".md,text/markdown" required></label><button><?= e(t('Import locally')) ?></button></form></details>
</div>
